contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint amount) public payable {
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted = false;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(c.depositsCount() == depositsBefore);
    }

    receive() external payable {}
}

